package android.graphics;import java.io.*;import javax.imageio.ImageIO;public class BitmapFactory{public static class Options{public boolean inScaled;public int inSampleSize=1;}public static Bitmap decodeResource(android.content.res.Resources r,int id){return decodeResource(r,id,new Options());}public static Bitmap decodeResource(android.content.res.Resources r,int id,Options options){try{String name=com.dominic.photosweep.R.names[id];for(String folder:new String[]{"drawable-nodpi","drawable"}){File f=new File("app/src/main/res/"+folder+"/"+name+".png");if(f.isFile())return new Bitmap(ImageIO.read(f));}return null;}catch(IOException e){throw new RuntimeException(e);}}}
